package crdt

import (
	"bytes"
	"testing"

	"github.com/stretchr/testify/require"
)

// Generated by Yjs 13.6.32: client 6 inserts <p> holding XmlHook("w") and the text "t" into fragment "y".
const hookInElementV1 = "0104060007010179030170070006000501778706010604000602017400"

// Yjs 13.6.32 lists a hook among a fragment's children, and renders it as "[object Object]" in toString.
func TestUnit_ContentType_XmlHookIsAnXMLChild(t *testing.T) {
	doc := New(WithClientID(3))
	require.NoError(t, ApplyUpdateV1(doc, mustHex(t, hookV1), nil))
	require.NoError(t, ApplyUpdateV1(doc, mustHex(t, hookInElementV1), nil))

	x := doc.GetXmlFragment("x")
	children := x.Children()
	require.Len(t, children, x.Len())
	require.Equal(t, "[object Object]", children[0].ToXML())
	require.Equal(t, "[object Object]<div></div>", x.ToXML())
	require.Equal(t, "<p>[object Object]t</p>", doc.GetXmlFragment("y").ToXML())

	hook, ok := children[0].(interface{ Get(string) (any, bool) })
	require.True(t, ok, "a hook child reads as a map")
	_, ok = hook.Get("a")
	require.False(t, ok)
}

// Yjs 13.6.32 get() returns the hook, a Y.Map subclass, from a map and from an array.
func TestUnit_ContentType_XmlHookGetReturnsAMap(t *testing.T) {
	doc := New(WithClientID(3))
	for _, u := range []string{hookV1, hookEditV1, hookArrayV1} {
		require.NoError(t, ApplyUpdateV1(doc, mustHex(t, u), nil))
	}

	v, ok := doc.GetMap("m").Get("hk")
	require.True(t, ok)
	hk, ok := v.(*YMap)
	require.True(t, ok, "Get returns %T", v)
	got, _ := hk.Get("b")
	require.Equal(t, "two", got)

	hookInArray, ok := doc.GetArray("a").Get(0).(*YMap)
	require.True(t, ok)
	got, _ = hookInArray.Get("k")
	require.Equal(t, "v", got)

	// A write through the map stays in the hook, which still encodes as type ref 5 named "h".
	doc.Transact(func(txn *Transaction) { hk.Set(txn, "c", "three") })
	m := New(WithClientID(4))
	require.NoError(t, ApplyUpdateV1(m, EncodeStateAsUpdateV1(doc, nil), nil))
	requireJSONOf(t, `{"hk":{"a":1,"b":"two","c":"three"},"z":3}`, m.GetMap("m").Entries())
	require.True(t, bytes.Contains(EncodeStateAsUpdateV1(m, nil), []byte{5, 1, 'h'}))
}
